import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
class ProfilePage extends StatefulWidget{const ProfilePage({super.key});@override State<ProfilePage>createState()=>_ProfilePageState();}
class _ProfilePageState extends State<ProfilePage>{final name=TextEditingController(),district=TextEditingController(),upazila=TextEditingController(),phone=TextEditingController();@override void initState(){super.initState();load();}Future<void>load()async{final p=await SharedPreferences.getInstance();name.text=p.getString('farmer_name')??'';district.text=p.getString('district')??'';upazila.text=p.getString('upazila')??'';phone.text=p.getString('phone')??'';}Future<void>save()async{final p=await SharedPreferences.getInstance();await p.setString('farmer_name',name.text.trim());await p.setString('district',district.text.trim());await p.setString('upazila',upazila.text.trim());await p.setString('phone',phone.text.trim());if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Profile saved')));} @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Farmer Profile',style:TextStyle(fontWeight:FontWeight.w700))),body:ListView(padding:const EdgeInsets.all(18),children:[const CircleAvatar(radius:38,child:Icon(Icons.person,size:42)),const SizedBox(height:18),TextField(controller:name,decoration:const InputDecoration(labelText:'Farmer name')),TextField(controller:district,decoration:const InputDecoration(labelText:'District')),TextField(controller:upazila,decoration:const InputDecoration(labelText:'Upazila')),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Phone (optional)')),const SizedBox(height:20),FilledButton.icon(onPressed:save,icon:const Icon(Icons.save_outlined),label:const Padding(padding:EdgeInsets.symmetric(vertical:14),child:Text('Save Profile')))]));}
